// Auto-generated icon assets from htmlshare_icon_fullbleed_moonlight
const FAVICON_64_BASE64 = "";
const APPLE_TOUCH_180_BASE64 = "";

function decodeBase64(b64: string): Uint8Array {
  const bin = atob(b64);
  const bytes = new Uint8Array(bin.length);
  for (let i = 0; i < bin.length; i++) {
    bytes[i] = bin.charCodeAt(i);
  }
  return bytes;
}

export function getFaviconPng(): Uint8Array {
  return decodeBase64(FAVICON_64_BASE64);
}

export function getAppleTouchIconPng(): Uint8Array {
  return decodeBase64(APPLE_TOUCH_180_BASE64);
}
